//! Bounded metadata-only updates of PDFs generated by ReadMD's engines.
//! Page, font, image, annotation and structure objects are never rewritten.
use crate::publication_metadata::PublicationMetadata;
use lopdf::{Document, Object, Stream, StringFormat};

const ERROR: &str = "publication_metadata_pdf";
const MAX_PDF: usize = 32 * 1024 * 1024;
const MAX_XMP: usize = 1024 * 1024;
fn pdf_string(value: &str) -> Object {
    let bytes = [0xfe, 0xff]
        .into_iter()
        .chain(value.encode_utf16().flat_map(u16::to_be_bytes))
        .collect::<Vec<_>>();
    Object::String(bytes, StringFormat::Hexadecimal)
}
fn owned(namespace: &str, local: &str) -> bool {
    match namespace {
        "http://purl.org/dc/elements/1.1/" => matches!(
            local,
            "title"
                | "creator"
                | "contributor"
                | "subject"
                | "description"
                | "identifier"
                | "rights"
                | "language"
                | "publisher"
                | "date"
        ),
        "http://ns.adobe.com/xap/1.0/" => local == "Identifier",
        "urn:readmd:publication:v1:" => local == "metadata",
        _ => false,
    }
}
/// Preserve unrelated engine XMP and replace only publication-owned fields.
fn merge_xmp(old: Option<&[u8]>, metadata: &PublicationMetadata) -> Result<Vec<u8>, String> {
    use quick_xml::{
        events::{BytesEnd, BytesStart, Event},
        name::ResolveResult,
        NsReader, Writer, XmlVersion,
    };
    const RDF: &str = "http://www.w3.org/1999/02/22-rdf-syntax-ns#";
    let current = crate::publication_metadata_formats::xmp(metadata);
    if current.len() > MAX_XMP {
        return Err(ERROR.into());
    }
    let Some(old) = old else {
        return Ok(current.into_bytes());
    };
    if old.len() > MAX_XMP {
        return Err(ERROR.into());
    }
    let text = std::str::from_utf8(old).map_err(|_| ERROR)?;
    let begin = current.find("<rdf:Description ").ok_or(ERROR)?;
    let end = current.find("</rdf:Description>").ok_or(ERROR)? + "</rdf:Description>".len();
    let addition = current[begin..end].replacen(
        "<rdf:Description ",
        "<rdf:Description xmlns:rdf=\"http://www.w3.org/1999/02/22-rdf-syntax-ns#\" ",
        1,
    );
    let mut reader = NsReader::from_str(text);
    reader.config_mut().check_end_names = true;
    let mut writer = Writer::new(Vec::new());
    // A true frame is this document's direct RDF Description. It never
    // propagates into engine structures, other subjects or blank nodes.
    let mut frames = Vec::<bool>::new();
    let mut skip = None;
    let mut rdf_depth = None;
    let mut rdf_count = 0;
    let mut roots = 0;
    let mut count = 0;
    loop {
        count += 1;
        if count > 50000 {
            return Err(ERROR.into());
        }
        let (namespace, event) = reader.read_resolved_event().map_err(|_| ERROR)?;
        let namespace = match namespace {
            ResolveResult::Bound(uri) => uri.as_ref().to_string(),
            ResolveResult::Unbound => String::new(),
            ResolveResult::Unknown(_) => return Err(ERROR.into()),
        };
        match &event {
            Event::DocType(_) => return Err(ERROR.into()),
            Event::End(end) => {
                let depth = frames.len();
                frames.pop().ok_or(ERROR)?;
                if let Some(at) = skip {
                    if at == depth {
                        skip = None;
                    }
                    continue;
                }
                if rdf_depth == Some(depth)
                    && namespace == RDF
                    && end.local_name().as_ref() == "RDF"
                {
                    writer.get_mut().extend_from_slice(addition.as_bytes());
                    rdf_depth = None;
                }
            }
            Event::Eof => break,
            _ if skip.is_some() => {
                if matches!(event, Event::Start(_)) {
                    frames.push(false);
                    if frames.len() > 32 {
                        return Err(ERROR.into());
                    }
                }
                continue;
            }
            Event::Text(text)
                if frames.is_empty() && !text.as_ref().chars().all(char::is_whitespace) =>
            {
                return Err(ERROR.into())
            }
            _ => (),
        }
        if let Event::Start(start) | Event::Empty(start) = &event {
            let depth = frames.len() + 1;
            let empty = matches!(event, Event::Empty(_));
            if depth > 32 {
                return Err(ERROR.into());
            }
            if depth == 1 {
                roots += 1;
                if roots != 1 {
                    return Err(ERROR.into());
                }
            }
            let is_rdf =
                namespace == RDF && start.local_name().as_ref() == "RDF" && rdf_depth.is_none();
            if is_rdf {
                rdf_count += 1;
                if rdf_count != 1 {
                    return Err(ERROR.into());
                }
                if !empty {
                    rdf_depth = Some(depth);
                }
            }
            if frames.last() == Some(&true) && owned(&namespace, start.local_name().as_ref()) {
                if !empty {
                    frames.push(false);
                    skip = Some(depth);
                }
                continue;
            }
            let mut document_description = rdf_depth == Some(depth - 1)
                && namespace == RDF
                && start.local_name().as_ref() == "Description";
            let mut has_document_subject = false;
            for attr in start.attributes() {
                let attr = attr.map_err(|_| ERROR)?;
                let (namespace, local) = reader.resolver().resolve_attribute(attr.key);
                if let ResolveResult::Bound(uri) = namespace {
                    if uri.as_ref() == RDF {
                        if matches!(local.as_ref(), "ID" | "nodeID") {
                            document_description = false;
                        } else if local.as_ref() == "about" {
                            has_document_subject = attr
                                .normalized_value(XmlVersion::Implicit1_0)
                                .map_err(|_| ERROR)?
                                .is_empty();
                            if !has_document_subject {
                                document_description = false;
                            }
                        }
                    }
                }
            }
            // An omitted rdf:about denotes an anonymous RDF resource, not
            // the document. Preserve it just like an explicit rdf:nodeID.
            document_description &= has_document_subject;
            let name = start.name().as_ref().to_string();
            let mut filtered = BytesStart::new(name.clone());
            for attr in start.attributes() {
                let attr = attr.map_err(|_| ERROR)?;
                let (namespace, local) = reader.resolver().resolve_attribute(attr.key);
                let remove = match namespace {
                    ResolveResult::Bound(uri) => {
                        document_description && owned(uri.as_ref(), local.as_ref())
                    }
                    ResolveResult::Unbound => false,
                    ResolveResult::Unknown(_) => return Err(ERROR.into()),
                };
                if !remove {
                    filtered.push_attribute(attr);
                }
            }
            if is_rdf && empty {
                writer
                    .write_event(Event::Start(filtered))
                    .map_err(|_| ERROR)?;
                writer.get_mut().extend_from_slice(addition.as_bytes());
                writer
                    .write_event(Event::End(BytesEnd::new(name)))
                    .map_err(|_| ERROR)?;
            } else {
                writer
                    .write_event(if empty {
                        Event::Empty(filtered)
                    } else {
                        Event::Start(filtered)
                    })
                    .map_err(|_| ERROR)?;
                if !empty {
                    frames.push(document_description);
                }
            }
        } else {
            writer.write_event(event).map_err(|_| ERROR)?;
        }
    }
    if rdf_count != 1
        || roots != 1
        || !frames.is_empty()
        || skip.is_some()
        || writer.get_ref().len() > MAX_XMP
    {
        return Err(ERROR.into());
    }
    Ok(writer.into_inner())
}

fn xmp_content(stream: &Stream) -> Result<Vec<u8>, String> {
    use std::io::Read;
    if stream.dict.get(b"Filter").is_err() {
        if stream.content.len() > MAX_XMP {
            return Err(ERROR.into());
        }
        return Ok(stream.content.clone());
    }
    let filters = stream.filters().map_err(|_| ERROR)?;
    if filters.as_slice() != [b"FlateDecode".as_slice()] || stream.dict.has(b"DecodeParms") {
        return Err(ERROR.into());
    }
    let mut output = Vec::new();
    flate2::read::ZlibDecoder::new(stream.content.as_slice())
        .take((MAX_XMP + 1) as u64)
        .read_to_end(&mut output)
        .map_err(|_| ERROR)?;
    if output.len() > MAX_XMP {
        return Err(ERROR.into());
    }
    Ok(output)
}
fn validate_unsigned(document: &Document) -> Result<(), String> {
    fn dictionary(
        dict: &lopdf::Dictionary,
        depth: usize,
        remaining: &mut usize,
    ) -> Result<(), String> {
        if dict.has(b"ByteRange")
            || dict.has(b"DocMDP")
            || dict.get(b"Type").is_ok_and(|value| {
                value
                    .as_name()
                    .is_ok_and(|name| matches!(name, b"Sig" | b"DocTimeStamp"))
            })
            || dict
                .get(b"TransformMethod")
                .is_ok_and(|value| value.as_name().is_ok_and(|name| name == b"DocMDP"))
        {
            return Err(ERROR.into());
        }
        for (_, value) in dict.iter() {
            visit(value, depth + 1, remaining)?;
        }
        Ok(())
    }
    fn visit(object: &Object, depth: usize, remaining: &mut usize) -> Result<(), String> {
        if depth > 32 || *remaining == 0 {
            return Err(ERROR.into());
        }
        *remaining -= 1;
        match object {
            Object::Array(values) => {
                for value in values {
                    visit(value, depth + 1, remaining)?;
                }
            }
            Object::Dictionary(dict) => dictionary(dict, depth, remaining)?,
            Object::Stream(stream) => dictionary(&stream.dict, depth, remaining)?,
            // Every indirect object is visited below. Do not follow references
            // recursively: page Parent links and shared resources contain cycles.
            _ => (),
        }
        Ok(())
    }
    let mut remaining = 1_000_000;
    dictionary(&document.trailer, 0, &mut remaining)?;
    for object in document.objects.values() {
        visit(object, 0, &mut remaining)?;
    }
    Ok(())
}

pub fn apply(bytes: &[u8], metadata: &PublicationMetadata) -> Result<Vec<u8>, String> {
    if !metadata.declared {
        return Ok(bytes.to_vec());
    }
    if bytes.len() > MAX_PDF {
        return Err(ERROR.into());
    }
    let document = Document::load_mem(bytes).map_err(|_| ERROR)?;
    if document.is_encrypted() || document.objects.len() > 200000 {
        return Err(ERROR.into());
    }
    // This helper handles owned engine output only, never a signed input PDF.
    validate_unsigned(&document)?;
    let root = document
        .trailer
        .get(b"Root")
        .and_then(Object::as_reference)
        .map_err(|_| ERROR)?;
    let old_xmp = match document.catalog().map_err(|_| ERROR)?.get(b"Metadata") {
        Ok(Object::Reference(id)) => Some(xmp_content(
            document
                .get_object(*id)
                .and_then(Object::as_stream)
                .map_err(|_| ERROR)?,
        )?),
        Ok(Object::Stream(stream)) => Some(xmp_content(stream)?),
        Err(_) => None,
        _ => return Err(ERROR.into()),
    };
    let xmp = merge_xmp(old_xmp.as_deref(), metadata)?;
    let info = document
        .trailer
        .get(b"Info")
        .ok()
        .and_then(|obj| match obj {
            Object::Reference(id) => document.get_object(*id).ok(),
            other => Some(other),
        })
        .and_then(|obj| obj.as_dict().ok())
        .cloned()
        .unwrap_or_default();
    let mut update = lopdf::IncrementalDocument::create_from(bytes.to_vec(), document);
    update
        .opt_clone_object_to_new_document(root)
        .map_err(|_| ERROR)?;
    let metadata_id = update.new_document.add_object(Stream::new(
        lopdf::dictionary! {"Type"=>"Metadata","Subtype"=>"XML"},
        xmp,
    ));
    let catalog = update
        .new_document
        .get_object_mut(root)
        .and_then(Object::as_dict_mut)
        .map_err(|_| ERROR)?;
    catalog.set("Metadata", metadata_id);
    if let Some(language) = &metadata.language {
        catalog.set("Lang", Object::string_literal(language.as_bytes()));
    } else if metadata.cleared_fields.contains("language") {
        catalog.remove(b"Lang");
    }
    let mut info = info;
    info.set("Title", pdf_string(&metadata.title));
    info.set("Author", pdf_string(&metadata.author_text()));
    if let Some(subject) = &metadata.subject {
        info.set("Subject", pdf_string(subject));
    } else {
        info.remove(b"Subject");
    }
    if metadata.keywords.is_empty() {
        info.remove(b"Keywords");
    } else {
        info.set("Keywords", pdf_string(&metadata.keywords.join("; ")));
    }
    let info_id = update.new_document.add_object(info);
    update.new_document.trailer.set("Info", info_id);
    let mut out = Vec::new();
    update.save_to(&mut out).map_err(|_| ERROR)?;
    if out.len() > MAX_PDF || !out.starts_with(bytes) {
        return Err(ERROR.into());
    }
    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn nested_signatures_and_docmdp_reject_real_pdf_updates() {
        let metadata = PublicationMetadata {
            title: "Owned output".into(),
            declared: true,
            ..Default::default()
        };
        for protected in [
            lopdf::dictionary! {"ByteRange"=>vec![0.into(),10.into(),20.into(),30.into()]},
            lopdf::dictionary! {"Type"=>"Sig"},
            lopdf::dictionary! {"Type"=>"DocTimeStamp"},
            lopdf::dictionary! {"DocMDP"=>Object::Reference((500,0))},
            lopdf::dictionary! {"TransformMethod"=>"DocMDP"},
        ] {
            let mut pdf = Document::with_version("1.7");
            let pages = pdf.add_object(
                lopdf::dictionary! {"Type"=>"Pages", "Kids"=>Vec::<Object>::new(), "Count"=>0},
            );
            let nested = Object::Array(vec![Object::Dictionary(
                lopdf::dictionary! {"Value"=>Object::Dictionary(protected)},
            )]);
            let root = pdf.add_object(
                lopdf::dictionary! {"Type"=>"Catalog", "Pages"=>pages, "Perms"=>nested},
            );
            pdf.trailer.set("Root", root);
            let mut bytes = Vec::new();
            pdf.save_to(&mut bytes).unwrap();
            let before = bytes.clone();
            assert_eq!(apply(&bytes, &metadata).unwrap_err(), ERROR);
            assert_eq!(bytes, before);
        }
    }
    #[test]
    fn unsigned_scan_bounds_nesting_and_does_not_follow_reference_cycles() {
        let mut pdf = Document::with_version("1.7");
        let id = pdf.new_object_id();
        pdf.objects
            .insert(id, lopdf::dictionary! {"Parent"=>id}.into());
        pdf.trailer.set("Root", id);
        validate_unsigned(&pdf).unwrap();
        let mut nested = Object::Null;
        for _ in 0..34 {
            nested = Object::Array(vec![nested]);
        }
        pdf.add_object(nested);
        assert!(validate_unsigned(&pdf).is_err());
    }
    #[test]
    fn only_document_direct_owned_xmp_properties_are_replaced() {
        let old = r#"<r:RDF xmlns:r="http://www.w3.org/1999/02/22-rdf-syntax-ns#" xmlns:d="http://purl.org/dc/elements/1.1/" xmlns:e="urn:engine"><r:Description r:about="" d:title="document-old"><d:title>document-element-old</d:title><e:structure><r:Description d:title="nested-attribute"><d:title>nested-element</d:title></r:Description></e:structure></r:Description><r:Description r:about="urn:other" d:title="other-attribute"><d:title>other-element</d:title></r:Description><r:Description r:nodeID="blank" d:title="blank-attribute"><d:title>blank-element</d:title></r:Description><r:Description d:title="anonymous-attribute"><d:title>anonymous-element</d:title></r:Description></r:RDF>"#;
        let metadata = PublicationMetadata {
            title: "New & 中文😀".into(),
            declared: true,
            ..Default::default()
        };
        let merged =
            String::from_utf8(merge_xmp(Some(old.as_bytes()), &metadata).unwrap()).unwrap();
        assert!(!merged.contains("document-old"));
        assert!(!merged.contains("document-element-old"));
        for retained in [
            "nested-attribute",
            "nested-element",
            "other-attribute",
            "other-element",
            "blank-attribute",
            "blank-element",
            "anonymous-attribute",
            "anonymous-element",
        ] {
            assert!(merged.contains(retained), "lost {retained}");
        }
        assert!(merged.contains("New &amp; 中文😀"));
        let mut reader = quick_xml::NsReader::from_str(&merged);
        loop {
            let (namespace, event) = reader.read_resolved_event().unwrap();
            assert!(!matches!(
                namespace,
                quick_xml::name::ResolveResult::Unknown(_)
            ));
            if matches!(event, quick_xml::events::Event::Eof) {
                break;
            }
        }
    }
    #[test]
    fn empty_rdf_accepts_metadata_and_stays_well_formed() {
        let metadata = PublicationMetadata {
            title: "Inserted".into(),
            declared: true,
            ..Default::default()
        };
        for old in [
            r#"<r:RDF xmlns:r="http://www.w3.org/1999/02/22-rdf-syntax-ns#"/>"#,
            r#"<x:xmpmeta xmlns:x="adobe:ns:meta/" xmlns:r="http://www.w3.org/1999/02/22-rdf-syntax-ns#"><r:RDF/></x:xmpmeta>"#,
        ] {
            let merged =
                String::from_utf8(merge_xmp(Some(old.as_bytes()), &metadata).unwrap()).unwrap();
            assert_eq!(merged.matches("<rdf:Description ").count(), 1);
            assert!(merged.contains("Inserted"));
            let mut reader = quick_xml::Reader::from_str(&merged);
            loop {
                if matches!(reader.read_event().unwrap(), quick_xml::events::Event::Eof) {
                    break;
                }
            }
        }
    }
    #[test]
    fn xmp_decompression_is_bounded_before_allocation_and_info_is_unicode() {
        use std::io::Write;
        let plain = Stream::new(lopdf::dictionary! {}, b"<test/>".to_vec());
        assert_eq!(xmp_content(&plain).unwrap(), b"<test/>");
        let compressed = |content: &[u8]| {
            let mut encoder =
                flate2::write::ZlibEncoder::new(Vec::new(), flate2::Compression::default());
            encoder.write_all(content).unwrap();
            Stream::new(
                lopdf::dictionary! {"Filter"=>"FlateDecode"},
                encoder.finish().unwrap(),
            )
        };
        assert_eq!(xmp_content(&compressed(b"<test/>")).unwrap(), b"<test/>");
        assert!(xmp_content(&compressed(&vec![b'x'; MAX_XMP + 1])).is_err());
        assert!(xmp_content(&Stream::new(
            lopdf::dictionary! {"Filter"=>"LZWDecode"},
            vec![]
        ))
        .is_err());
        let mut predictor = compressed(b"<test/>");
        predictor
            .dict
            .set("DecodeParms", lopdf::dictionary! {"Predictor"=>12});
        assert!(xmp_content(&predictor).is_err());
        let encoded = pdf_string("中文😀");
        assert_eq!(
            encoded.as_str().unwrap(),
            &[0xfe, 0xff, 0x4e, 0x2d, 0x65, 0x87, 0xd8, 0x3d, 0xde, 0x00]
        );
    }
    #[test]
    fn metadata_increment_preserves_pages_fonts_links_engine_xmp_and_info() {
        let mut pdf = Document::with_version("1.7");
        let pages = pdf.new_object_id();
        let content = pdf.add_object(Stream::new(
            lopdf::dictionary! {},
            b"BT (unchanged) Tj ET".to_vec(),
        ));
        let page=pdf.add_object(lopdf::dictionary!{"Type"=>"Page","Parent"=>pages,"Contents"=>content,"MediaBox"=>vec![0.into(),0.into(),100.into(),100.into()]});
        pdf.objects.insert(
            pages,
            lopdf::dictionary! {"Type"=>"Pages","Kids"=>vec![page.into()],"Count"=>1}.into(),
        );
        let old = r#"<x:xmpmeta xmlns:x="adobe:ns:meta/"><r:RDF xmlns:r="http://www.w3.org/1999/02/22-rdf-syntax-ns#"><r:Description r:about="" xmlns:d="http://purl.org/dc/elements/1.1/" xmlns:p="urn:engine:test" d:title="Old"><d:creator><r:Seq><r:li>Old</r:li></r:Seq></d:creator><p:untouched>engine data</p:untouched></r:Description></r:RDF></x:xmpmeta>"#;
        let xmp = pdf.add_object(Stream::new(
            lopdf::dictionary! {"Type"=>"Metadata","Subtype"=>"XML"},
            old.as_bytes().to_vec(),
        ));
        let root=pdf.add_object(lopdf::dictionary!{"Type"=>"Catalog","Pages"=>pages,"Metadata"=>xmp,"PageMode"=>"UseOutlines"});
        pdf.trailer.set("Root", root);
        let info=pdf.add_object(lopdf::dictionary!{"Creator"=>Object::string_literal("Original engine"),"Title"=>Object::string_literal("Old")});
        pdf.trailer.set("Info", info);
        let mut before = Vec::new();
        pdf.save_to(&mut before).unwrap();
        let metadata=crate::publication_metadata::from_source("---\ntitle: New\nauthors: ['Lovelace, Ada', Grace]\nkeywords: [one, two]\nlang: fr-CA\n---\nBody",&serde_json::json!({}),"Book").unwrap();
        let after = apply(&before, &metadata).unwrap();
        assert!(after.starts_with(&before));
        let result = Document::load_mem(&after).unwrap();
        assert_eq!(result.get_pages().len(), 1);
        assert_eq!(
            result.get_object(page).unwrap(),
            pdf.get_object(page).unwrap()
        );
        assert_eq!(
            result.get_object(content).unwrap(),
            pdf.get_object(content).unwrap()
        );
        let catalog = result.catalog().unwrap();
        assert_eq!(
            catalog.get(b"PageMode").unwrap().as_name().unwrap(),
            b"UseOutlines"
        );
        assert_eq!(catalog.get(b"Lang").unwrap().as_str().unwrap(), b"fr-CA");
        let id = catalog.get(b"Metadata").unwrap().as_reference().unwrap();
        let xml = String::from_utf8(
            result
                .get_object(id)
                .unwrap()
                .as_stream()
                .unwrap()
                .decompressed_content()
                .unwrap(),
        )
        .unwrap();
        assert!(xml.contains("<p:untouched>engine data</p:untouched>"));
        assert!(!xml.contains("Old"));
        assert!(xml.contains("Lovelace, Ada</rdf:li><rdf:li>Grace"));
        let id = result.trailer.get(b"Info").unwrap().as_reference().unwrap();
        assert_eq!(
            result
                .get_object(id)
                .unwrap()
                .as_dict()
                .unwrap()
                .get(b"Creator")
                .unwrap()
                .as_str()
                .unwrap(),
            b"Original engine"
        );
    }
    #[test]
    fn rejects_ambiguous_or_unsafe_xmp_instead_of_overwriting_engine_properties() {
        let metadata = PublicationMetadata {
            title: "Test".into(),
            declared: true,
            ..Default::default()
        };
        for xml in ["<broken>","<!DOCTYPE x><rdf:RDF xmlns:rdf=\"http://www.w3.org/1999/02/22-rdf-syntax-ns#\"/>","<x><rdf:RDF xmlns:rdf=\"http://www.w3.org/1999/02/22-rdf-syntax-ns#\"></rdf:RDF><rdf:RDF xmlns:rdf=\"http://www.w3.org/1999/02/22-rdf-syntax-ns#\"></rdf:RDF></x>"]{assert!(merge_xmp(Some(xml.as_bytes()),&metadata).is_err());}
    }
}
